import { Controller, useForm, type SubmitHandler } from "react-hook-form";

type Review = { rating: number };
type RatingProps = { value: number; onChange: (value: number) => void };

function Rating({ value, onChange }: RatingProps) {
  return (
    <div aria-label="Rating">
      {[1, 2, 3, 4, 5].map((score) => (
        <button key={score} type="button" onClick={() => onChange(score)}>
          {score <= value ? "★" : "☆"}
        </button>
      ))}
    </div>
  );
}

export default function ReviewForm() {
  const { control, handleSubmit } = useForm<Review>({
    defaultValues: { rating: 0 },
  });
  const submit: SubmitHandler<Review> = (data) => alert(data.rating);

  return (
    <form onSubmit={handleSubmit(submit)}>
      <Controller
        name="rating"
        control={control}
        rules={{ min: { value: 1, message: "Choose a rating" } }}
        render={({ field, fieldState }) => (
          <>
            <Rating value={field.value} onChange={field.onChange} />
            {fieldState.error && <p>{fieldState.error.message}</p>}
          </>
        )}
      />
      <button type="submit">Send review</button>
    </form>
  );
}
