import { useForm, type SubmitHandler } from "react-hook-form";

type Account = { email: string; age: number };

async function saveAccount(data: Account) {
  await Promise.resolve();
  if (data.email.endsWith("@blocked.example")) {
    throw new Error("That email cannot be registered");
  }
}

export default function AccountForm() {
  const {
    register, handleSubmit, setError,
    formState: { errors, isSubmitting },
  } = useForm<Account>({ defaultValues: { email: "", age: 18 } });

  const submit: SubmitHandler<Account> = async (data) => {
    try {
      await saveAccount(data);
      alert("Account created");
    } catch (error) {
      setError("email", {
        type: "server",
        message: error instanceof Error ? error.message : "Request failed",
      });
    }
  };

  return (
    <form onSubmit={handleSubmit(submit)} noValidate>
      <input type="email" {...register("email", { required: "Email is required" })} />
      {errors.email && <p>{errors.email.message}</p>}
      <input type="number" {...register("age", {
        valueAsNumber: true, min: { value: 18, message: "You must be 18 or older" },
      })} />
      {errors.age && <p>{errors.age.message}</p>}
      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? "Saving…" : "Create account"}
      </button>
    </form>
  );
}
